import os, re

def load_grids():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
    G = {}

    # Pattern: "Demo pair N input/output" or "Test input (HxW):"
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h_str, w_str = m[1], int(m[2]), int(m[3])
        content_start = m.end()
        if k not in G:
            lines = []
            for i in range(1, 60):  # reasonable height
                line = t[content_start:].split('\n')[i-1].strip() if content_start+i < len(t) else ''
                if not line.startswith('Demo') and not line.startswith('Test'):
                    if line:
                        rows = line.split()
                        if len(rows) == w_str and all(x.isdigit() for x in rows):
                            lines.append([int(x) for x in rows])
                        else:
                            break
            if lines:
                G[k] = {'rows': lines, 'h': len(lines), 'w': w_str}
    return G

G = load_grids()
print("Grids found:", sorted(G.keys()))
for k, v in sorted(G.items()):
    print(f"\n=== {k} ({v['h']}x{v['w']}) ===")
    for row in v['rows']:
        print(row)

