import os, re, time
time.sleep(1)

def load_grids():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}
    sessions_path = os.path.join(d, '../../sessions')
    base_name = os.path.basename(d)
    jsonl_path = os.path.join(sessions_path, base_name + '.jsonl')
    print(f"Looking for: {jsonl_path}")

    import glob
    files = glob.glob(os.path.join(sessions_path, '*.jsonl'))
    print("Session files found:", files[:5])

    G = {}
    for f in files[-3:]:  # most recent
        with open(f) as fp:
            content = fp.read()

        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
            k, h_str, w_str = m[1], int(m[2]), int(m[3])
            content_start = m.end()
            lines = []
            for i in range(1, 60):
                idx = content_start - len(content) + content.start()
                if content.startswith('Demo' * 50):
                    break
                rest = content[m.end():].split('\n')[i-1] if m.end()+i*30 < len(content) else ''
                if rest.strip() and not rest.startswith(('Demo', 'Test')):
                    rows = rest.strip().split()
                    if len(rows) == w_str and all(x.isdigit() for x in rows):
                        lines.append([int(x) for x in rows])
                    else:
                        break
            if lines:
                G[k] = {'rows': lines, 'h': len(lines), 'w': w_str}
    return G

G = load_grids()
print("Grids found:", sorted(G.keys()))

